"""Buildless cPanel-compatible visual concept; no external dependencies."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1]
PAGES = [('index.html', 'Acasă'), ('meniu.html', 'Meniu'), ('evenimente.html', 'Evenimente'), ('galerie.html', 'Galerie'), ('contact.html', 'Contact')]

def header(current):
    links = ''.join(f'<a href="{url}"'+(' aria-current="page"' if url == current else '')+f'>{title}</a>' for url, title in PAGES)
    return f'''<a class="skip" href="#continut">Sari la conținut</a>
<header class="site-header"><a class="brand" href="index.html" aria-label="Old Mike Pub, Acasă"><img src="assets/brand/oldmike-logo.png" width="73" height="73" alt="Logo oficial Old Mike"><span class="brand-name">OLD MIKE<small>PUB · BUCUREȘTI</small></span></a>
<button class="nav-toggle" aria-controls="site-nav" aria-expanded="false" aria-label="Deschide meniul" type="button">☰</button>
<nav class="site-nav" id="site-nav" aria-label="Navigare principală">{links}<a href="https://club.oldmike.ro/">Old Mike Club <span aria-hidden="true">↗</span></a></nav>
<a class="header-cta" href="tel:+40787366166">Rezervă o masă <span aria-hidden="true">↗</span></a></header>'''

def footer():
    return '''<footer class="site-footer"><span>OLD MIKE PUB <span aria-hidden="true"> · </span> Mâncare bună. Oameni faini.</span><a class="footer-phone" href="tel:+40787366166">Rezervări · 0787 366 166</a></footer>'''

def button(href, text, ghost=False):
    return f'<a class="button{" ghost" if ghost else ""}" href="{href}">{text} <span class="arrow" aria-hidden="true">↗</span></a>'

def intro(kicker, title, text):
    return f'<div class="page-intro"><div><div class="eyebrow">{kicker}</div><h1>{title}</h1></div><p class="intro">{text}</p></div>'

home = f'''<main id="continut"><section class="home-hero" aria-labelledby="hero-title"><picture class="hero-media"><source media="(max-width:800px)" srcset="assets/images/hero-burger-mobile-v1.webp"><img src="assets/images/hero-burger-v1.webp" width="1536" height="1024" alt="Concept culinar: burger fotografiat în lumină caldă" fetchpriority="high" decoding="async"></picture>
<div class="hero-copy"><div class="eyebrow">Gust bun. Companie bună.</div><h1 id="hero-title">Poftă de<br><em>ceva bun.</em></h1><p class="intro">Mâncare bună, bere rece și oamenii tăi.<br>Ne vedem la Old Mike.</p><div class="actions">{button('meniu.html','Descoperă meniul')}{button('tel:+40787366166','Rezervă o masă',True)}</div><div class="hero-detail">Old Mike Pub · București</div></div></section></main>'''

menu = f'''<main id="continut" class="page-main">{intro('La ce ți-e poftă?', 'Gusturi pentru<br><em>seri bune.</em>', 'Câteva idei pentru următoarea ieșire. Descoperă toate preparatele și băuturile în meniul complet.')}
<section class="menu-feature" aria-labelledby="burger-title"><picture><source media="(max-width:800px)" srcset="assets/images/hero-burger-mobile-v1.webp"><img src="assets/images/hero-burger-v1.webp" width="1536" height="1024" alt="Concept de prezentare a unui burger" decoding="async"></picture><div class="feature-copy"><span class="feature-index">01 / DE POFTĂ</span><h2 id="burger-title">Burgeri.<br><em>Greu de uitat.</em></h2><p>Unele seri încep simplu.<br>Cu un burger și oamenii potriviți.</p><a class="text-link" href="https://meniu.oldmike.ro/">Descoperă în meniu <span class="arrow" aria-hidden="true">↗</span></a></div></section>
<div class="menu-pair"><section class="menu-story"><img src="assets/images/pizza-concept.webp" width="900" height="1204" alt="Imagine de concept cu pizza" loading="lazy" decoding="async"><div class="story-copy"><span class="feature-index">02 / DE ÎMPĂRȚIT</span><h2>Încă o felie?</h2><p>Pizza, povești și timp petrecut împreună.</p><a class="text-link" href="https://meniu.oldmike.ro/">Vezi selecția de pizza <span class="arrow" aria-hidden="true">↗</span></a></div></section>
<section class="menu-story"><img src="assets/images/bere-concept.webp" width="900" height="1204" alt="Imagine de concept cu bere" loading="lazy" decoding="async"><div class="story-copy"><span class="feature-index">03 / DE CIOCNIT</span><h2>Noroc de seară.</h2><p>O bere rece și încă un motiv să mai rămâi.</p><a class="text-link" href="https://meniu.oldmike.ro/">Descoperă băuturile <span class="arrow" aria-hidden="true">↗</span></a></div></section></div>
<div class="menu-complete"><p><strong>Ai mai multe de descoperit.</strong><br>Toate produsele, prețurile și detaliile sunt în meniul complet.</p>{button('https://meniu.oldmike.ro/','Vezi meniul complet')}</div></main>'''

gallery = f'''<main id="continut" class="page-main">{intro('Locul nostru. Oamenii tăi.', 'Atmosferă de pub.<br><em>Spirit Old Mike.</em>', 'Un colț de terasă, un loc la bar și timp pentru o seară bună. Descoperă spațiul Old Mike.')}
<div class="gallery-grid"><figure class="gallery-item" style="margin-left:0;margin-right:0"><button class="gallery-button" data-gallery type="button" aria-label="Mărește fotografia terasei"><img src="assets/images/terrace-cinematic-v1.webp" width="1050" height="1400" alt="Terasa reală Old Mike, fotografie editată cinematic" decoding="async"></button><figcaption class="image-caption"><strong>La terasă</strong><span>Mărește fotografia ↗</span></figcaption></figure>
<figure class="gallery-item" style="margin-left:0;margin-right:0"><button class="gallery-button" data-gallery type="button" aria-label="Mărește fotografia barului"><img src="assets/images/bar-cinematic-v1.webp" width="1050" height="1400" alt="Barul real Old Mike, fotografie editată cinematic" loading="lazy" decoding="async"></button><figcaption class="image-caption"><strong>La bar</strong><span>Mărește fotografia ↗</span></figcaption></figure></div>
<dialog id="image-viewer" aria-label="Fotografie mărită"><button class="close-dialog" type="button" aria-label="Închide fotografia">×</button><img alt="Fotografie mărită"></dialog></main>'''

events = f'''<main id="continut" class="page-main">{intro('Ne strângem la Old Mike', 'Seri de trecut<br><em>în calendar.</em>', 'Meciuri, întâlniri și evenimente. Aici găsești ce urmează la Old Mike.')}
<div class="filters" role="group" aria-label="Filtrează evenimentele"><button class="filter" data-filter="all" aria-pressed="true" type="button">Toate</button><button class="filter" data-filter="sport" aria-pressed="false" type="button">Sport</button><button class="filter" data-filter="other" aria-pressed="false" type="button">Alte evenimente</button></div>
<section class="empty-events" aria-live="polite"><div class="event-icon" aria-hidden="true">OM.</div><h2>Următoarea ieșire?<br><em>O găsești aici.</em></h2><p>Nu sunt evenimente publicate în acest moment.<br>Revino pentru următoarele seri Old Mike.</p>{button('tel:+40787366166','Întreabă-ne despre rezervări',True)}</section>
<div class="events-bottom"><p>Ai deja planul pentru seară?<br>Rezervă telefonic la <a href="tel:+40787366166">0787 366 166</a>.</p><a class="text-link" href="meniu.html">Între timp, descoperă meniul <span class="arrow" aria-hidden="true">↗</span></a></div></main>'''

contact = f'''<main id="continut" class="page-main"><div class="contact-layout"><div><div class="eyebrow">O seară bună începe cu un telefon</div><h1>Ne vedem<br><em>la Old Mike.</em></h1><p>Vii cu prietenii, familia sau colegii?<br>Sună-ne pentru rezervări și detalii despre vizită.</p><div class="location-line">Old Mike Pub · București</div></div>
<section class="contact-card" aria-label="Rezervări și legături utile"><span class="label">Rezervări telefonice</span><a class="big-phone" href="tel:+40787366166">0787 366 166 <span aria-hidden="true">↗</span></a><div class="contact-links"><a class="text-link" href="meniu.html">Explorează meniul <span aria-hidden="true">↗</span></a><a class="text-link" href="https://club.oldmike.ro/">Intră în Old Mike Club <span aria-hidden="true">↗</span></a><a class="text-link" href="galerie.html">Descoperă locul <span aria-hidden="true">↗</span></a></div></section></div></main>'''

CONTENT = {'index.html': home, 'meniu.html': menu, 'evenimente.html': events, 'galerie.html': gallery, 'contact.html': contact}
for filename, title in PAGES:
    html = f'''<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#100e0b"><title>{escape(title)} · Old Mike Pub</title><meta name="description" content="Old Mike Pub. Mâncare bună, bere rece și seri cu oamenii tăi. Rezervări la 0787 366 166."><link rel="icon" type="image/png" href="assets/brand/oldmike-logo.png"><link rel="stylesheet" href="assets/site.css"></head><body class="{'home' if filename == 'index.html' else 'inner-page'}">{header(filename)}{CONTENT[filename]}{footer()}<script src="assets/site.js" defer></script></body></html>'''
    (ROOT / filename).write_text(html, encoding='utf-8')
print('Generated 5 pages; design concept, no deployment.')

admin = '''<main id="continut" class="page-main admin-demo"><div class="eyebrow">Administrare evenimente · demonstrație</div><h1 style="font-size:58px">Un poster.<br><em>O seară în calendar.</em></h1><p class="demo-notice">Aceasta este o demonstrație locală a formularului. Poți încărca și previzualiza un poster. Nu salvează și nu publică evenimente pe site.</p><form id="poster-form" class="admin-form"><label>Titlul evenimentului<input id="event-title" name="title" maxlength="120" required placeholder="Numele evenimentului"></label><div class="form-pair"><label>Categoria<select name="category" id="event-category"><option>Sport</option><option>Alte evenimente</option></select></label><label>Data și ora din București<input type="datetime-local" name="starts" id="event-start" required></label></div><label>Data și ora de încheiere, București<input type="datetime-local" name="ends" id="event-end" required></label><label>Posterul evenimentului · JPG, PNG sau WebP, maximum 8 MB<input type="file" id="event-poster" accept="image/jpeg,image/png,image/webp" required></label><div><button class="button" type="submit">Previzualizează posterul <span aria-hidden="true">↗</span></button></div><p class="status" role="status" id="poster-status"></p></form><section class="poster-preview" id="poster-result" hidden aria-label="Previzualizarea posterului"><img id="poster-image" alt=""><h2 id="poster-title"></h2><p id="poster-date" class="status"></p></section></main>'''
admin_js = '''(()=>{const form=document.getElementById('poster-form'),status=document.getElementById('poster-status'),result=document.getElementById('poster-result');let currentUrl;form.addEventListener('submit',e=>{e.preventDefault();result.hidden=true;status.textContent='';const file=document.getElementById('event-poster').files[0],start=document.getElementById('event-start').value,end=document.getElementById('event-end').value,title=document.getElementById('event-title').value.trim();if(!title){status.textContent='Completează titlul evenimentului.';return}if(end<=start){status.textContent='Încheierea trebuie să fie după începerea evenimentului.';return}if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){status.textContent='Alege o imagine JPG, PNG sau WebP de maximum 8 MB.';return}if(currentUrl)URL.revokeObjectURL(currentUrl);currentUrl=URL.createObjectURL(file);const img=document.getElementById('poster-image');img.onload=()=>{document.getElementById('poster-title').textContent=title;document.getElementById('poster-date').textContent=start.slice(0,10).split('-').reverse().join('.')+' · '+start.slice(11)+' — ora Bucureștiului';status.textContent='Previzualizare pregătită. Imaginea rămâne doar în browser; nu s-a publicat nimic.';result.hidden=false};img.onerror=()=>{status.textContent='Fișierul nu poate fi citit ca imagine. Alege alt poster.'};img.alt='Poster: '+title;img.src=currentUrl});})();'''
(ROOT/'administrare-demo.html').write_text('<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Demonstrație administrare · Old Mike Pub</title><link rel="stylesheet" href="assets/site.css"></head><body>'+header('')+admin+footer()+'<script src="assets/site.js" defer></script><script>'+admin_js+'</script></body></html>',encoding='utf-8')
print('Generated a clearly labelled local-only administration demonstration.')
